-- QUALITY CHECK LIST.xlsx: QC -Work heads and all 12 detailed sheets.
-- Preserves source checkpoint wording, duplicates, phases and serial numbers.
-- Run before deploying the quality checklist workspace. DDL precedes transactional seeds.
CREATE TABLE IF NOT EXISTS quality_checklist_templates (
  work_head VARCHAR(50) NOT NULL PRIMARY KEY, label VARCHAR(255) NOT NULL,
  serial_number INT NOT NULL, sheet_name VARCHAR(100) NOT NULL, title VARCHAR(255) NOT NULL,
  version VARCHAR(30) NOT NULL, checkpoints JSON NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

SET @qc_ddl = IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'quality_checklists' AND column_name = 'work_head') = 0,
  'ALTER TABLE quality_checklists ADD COLUMN work_head VARCHAR(50) NULL', 'SELECT 1');
PREPARE qc_stmt FROM @qc_ddl; EXECUTE qc_stmt; DEALLOCATE PREPARE qc_stmt;

SET @qc_ddl = IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'quality_checklists' AND column_name = 'template_version') = 0,
  'ALTER TABLE quality_checklists ADD COLUMN template_version VARCHAR(30) NULL', 'SELECT 1');
PREPARE qc_stmt FROM @qc_ddl; EXECUTE qc_stmt; DEALLOCATE PREPARE qc_stmt;

SET @qc_ddl = IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'quality_checklists' AND column_name = 'template_title') = 0,
  'ALTER TABLE quality_checklists ADD COLUMN template_title VARCHAR(255) NULL', 'SELECT 1');
PREPARE qc_stmt FROM @qc_ddl; EXECUTE qc_stmt; DEALLOCATE PREPARE qc_stmt;

SET @qc_ddl = IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'quality_checklists' AND column_name = 'template_sheet_name') = 0,
  'ALTER TABLE quality_checklists ADD COLUMN template_sheet_name VARCHAR(100) NULL', 'SELECT 1');
PREPARE qc_stmt FROM @qc_ddl; EXECUTE qc_stmt; DEALLOCATE PREPARE qc_stmt;

SET @qc_ddl = IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'quality_check_heads' AND column_name = 'work_head') = 0,
  'ALTER TABLE quality_check_heads ADD COLUMN work_head VARCHAR(50) NULL', 'SELECT 1');
PREPARE qc_stmt FROM @qc_ddl; EXECUTE qc_stmt; DEALLOCATE PREPARE qc_stmt;

SET @qc_ddl = IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'quality_check_heads' AND column_name = 'template_serial_number') = 0,
  'ALTER TABLE quality_check_heads ADD COLUMN template_serial_number INT NULL', 'SELECT 1');
PREPARE qc_stmt FROM @qc_ddl; EXECUTE qc_stmt; DEALLOCATE PREPARE qc_stmt;

START TRANSACTION;
INSERT INTO quality_checklist_templates (work_head,label,serial_number,sheet_name,title,version,checkpoints) VALUES (CONVERT(X'45584341564154494f4e' USING utf8mb4),CONVERT(X'45786361766174696f6e' USING utf8mb4),CONVERT(X'31' USING utf8mb4),CONVERT(X'45786361766174696f6e' USING utf8mb4),CONVERT(X'45786361766174696f6e' USING utf8mb4),CONVERT(X'3230323631303033' USING utf8mb4),CONVERT(X'5b5d' USING utf8mb4))
ON DUPLICATE KEY UPDATE label=VALUES(label),serial_number=VALUES(serial_number),sheet_name=VALUES(sheet_name),title=VALUES(title),version=VALUES(version),checkpoints=VALUES(checkpoints);
UPDATE quality_check_heads SET work_head=CONVERT(X'45584341564154494f4e' USING utf8mb4), template_serial_number=1, name=CONVERT(X'45786361766174696f6e' USING utf8mb4), is_active=1
WHERE TRIM(name) IN (CONVERT(X'45786361766174696f6e' USING utf8mb4)) OR work_head=CONVERT(X'45584341564154494f4e' USING utf8mb4);
SET @qc_next_sort = (SELECT COALESCE(MAX(sort_order),0)+1 FROM quality_check_heads);
INSERT INTO quality_check_heads (id,name,sort_order,is_active,work_head,template_serial_number,created_at,updated_at)
SELECT UUID(),CONVERT(X'45786361766174696f6e' USING utf8mb4),@qc_next_sort,1,CONVERT(X'45584341564154494f4e' USING utf8mb4),1,NOW(),NOW() WHERE NOT EXISTS (SELECT 1 FROM quality_check_heads WHERE work_head=CONVERT(X'45584341564154494f4e' USING utf8mb4));

